import type { Story } from "./stories";

export const stories2400: Record<number, Story> = {
	2400: {
		index: 2400,
		text: `<p>A laughing crowd draws your curiosity. However, you can't make your way through the throng of people so you decide to move along, certain you will hear all about it later. Sure enough, you do: an amusing tale of how the other, when trying to show off their power, stumbled on a stone and became trapping in a strange device. You are sure to tell this tale on your travels. [S1]</p>`,
	},
	2401: {
		index: 2401,
		text: `<p>A strange sight encompasses your vision—a huge 'efreet, bound hand and foot into a great stone cliff. Writing before the imprisoned creature reads, "A penitent man may free this djinn—but your faith must be strong." The sorrow of the 'efreet moves you to aid the poor soul.</p>
<p><b>No Skill:</b> You kneel and prostrate yourself, praying to the Most High for the djinn to be freed. Yet nothing happens. The 'efreet's eyes light with thanks for your attempt, and you strive to pray more at other times to strengthen your faith. [D1/Piety]</p>
<p><b>Piety:</b> You get on your knees and pray and beg, calling on the infinite virtues of the Most High. A loud crack, akin to thunder, echoes throughout the area—and the 'efreet is freed. He bows low to you. "I have been captive here for one hundred years and a day. Thank you, mortal, for my freedom." And with that, he disappears, leaving a wondrous object in his place. [D2/<b>Treasure</b>]</p>`,
	},
	2402: {
		index: 2402,
		text: `<p>A huge 'efreet stands before you suddenly and you immediately fall to your knees to beg for your life to be spared. After a long silence, you dare to look up and you see that the 'efreet is held fast by sparkling bands of power. Rather than pity, you are emboldened to taunt and jab at the helpless creature. Your words and blows do nothing and when the 'efreet makes even the slightest shift in position, fear grabs hold of you. Better to leave now with some dignity. [D1]</p>`,
	},
	2403: {
		index: 2403,
		text: `<p>Before the house of a wealthy merchant's house, a fearsome 'efreet stands guard. You plead not to be harmed. "I have no wish to harm you. But I am bound by love and promise to remain here, until such time as I successfully defend this home from an enemy." The other looks at you more closely. "You can help me and I, in turn, can make your business within a success." The plan requires you to attack the 'efreet in an effort to enter the abode without due introduction.</p>
<p><b>No Skill:</b> You comply, stabbing at the creature with your sword. A simple gesture turns your weapon into dust: then a clap of thunder shakes the abode. "I am free!" The 'efreet disappears into the house for a moment and then returns, carrying a screaming youth. "Now you are mine to love forever," you hear the 'efreet say before flying away. The merchant comes out wailing in anguish at the abduction of his child. You leave before the merchant notices you, but word of your foolishness still travels around. [<em>Scorned</em>]</p>
<p><b>Bargaining and Evaluation:</b> There is something not right about the whole idea. Your hesitation proves fruitful as just then, the merchant appears. "Ah, I see you have met my slave. Formerly he plagued my home in an attempt to abduct my daughter for a lover, but by cunning I have bound him here to watch over the place instead. He makes for a good guard against outside thieves and scoundrels." Moving inside, you conclude your business to your great profit. [S1/W+3 (Max: Rich)]</p>`,
	},
	2404: {
		index: 2404,
		text: `<p>You come across an attractive person beating a dog, who lovingly accepts the harsh treatment. You grab a passerby to ask why no one is stopping this and learn that the dog is actually an 'efreet who fell in love with the horrid person. To show its love agreed to transform into a dog, in which form he remains trapped, suffering such treatment as you have witnessed.</p>
<p><b>No Skill:</b> Despite the 'efreet's willingness, no one should suffer so. You pick up a stick and threaten the person with it—but the dog comes to her defense. You fend it off with the stick, but the dog proves very strong and you are made to retreat. [D1/Enduring Hardship]</p>
<p><b>Magic:</b> You cannot let this suffering go on. With some water, and chanted words of power, you are able to restore the other to its former self. Instead of taking revenge on the person, the 'efreet again declares undying love—which the human paramour snubs, storms away. The other turns to you with glaring eyes, and with a gesture, sends you sprawling on the ground. "Interfere not in matters of the heart!" He, too, storms away, in the other direction. [S1/<em>Scorned</em>]</p>`,
	},
	2405: {
		index: 2405,
		text: `<p>Love is stronger than faith and might, as the sight before you proves: a huge 'efreet being lorded over by a tiny human. In fact, the 'efreet seems to have no will of its own—is it ensorcelled? You wait for the creature to be separated from its lover (or master!) and when the opportunity arises, you slap him hard. Nothing. You beat the creature about the chest and head, but nothing changes. Finally, you give up, unsure of what it is that compels the 'efreet to maintain its loyalty to its human love. [D1/S1]</p>`,
	},
	2406: {
		index: 2406,
		text: `<p>Your eyes sting from gazing upon the otherworldly beauty in front of you. You fall to your knees and bow low, forehead touching the floor. Then, with carefully chosen words, plead for the 'efreeteh to allow herself to be seen by other mortals. She is deeply moved by your speech and manner.</p>
<p><b>No Skill:</b> She grabs your chin and lifts your head up and bestows a burning kiss upon your forehead. Your face is suffused with a glow that stays with you for many weeks. [D1/Appearance]</p>
<p><b>Protective Talisman</b> [mandatory]: You lift your head up and she approaches you—but she stops, an unseen force preventing her from coming any closer. A look of sadness passes across her face; then she throws you a kiss and disappears. [D1]</p>`,
	},
	2407: {
		index: 2407,
		text: `<p>You throw yourself before the 'efreeteh, babbling apologies for gazing upon her beauty. Disgusted by this display, she leaves your presence. You should have controlled your reactions more and will strive to learn from this error. [D-1/Courtly Graces]</p>`,
	},
	2408: {
		index: 2408,
		text: `<p>The ethereal beauty and haunting whispers of the 'efreeteh fill your head with promises of pleasure and power and you beg to be with her.</p>
<p><b>No Skill:</b> The 'efreeteh has no interest in you and disappears in a rather dramatic fashion. [D1]</p>
<p><b>Piety:</b> Your faith in Allah is too strong and you know the promises the 'efreeteh presents are all false and come with a steep price. You hurl words of power and faith at the other; she screams then shrinks into a point of light before disappearing with nary a sound. [D1/Wisdom]</p>
<p><b>Insane</b> [mandatory]: You feel your will slipping away. You become her slave, doing her bidding, fulfilling every whim, until the end of your days, which are longer than fated, extended by the power of your fiery master. [Death]</p>`,
	},
	2409: {
		index: 2409,
		text: `<p>The eerie beauty of the other holds false promises: it will spell doom to succumb to her wiles. You feel your will slipping away, so you summon yourself to anger and launch a fierce attack.</p>
<p><b>No Skill:</b> Shocked and surprised by your response, the other disappears in a fiery flash. [D2]</p>
<p><b>Sparkling Spear:</b> You thrust with the spear, exploding the other in a shower of fire, which consumes the spear. Thunder and lightning follow in quick succession and in the place where the 'efreeteh stood lies a curious object. [D2/Lose <b>Sparkling Spear</b>/<b>Thunderbolt Sword</b>]</p>`,
	},
	2410: {
		index: 2410,
		text: `<p>As you gaze takes upon the otherworldly beauty of the other, your mind becomes possessed and a will not your own drives you to attack. "I only sought to love a mortal," the other says in sorrow before disappearing. You are sure a doom has been averted today. [S1/Piety]</p>`,
	},
	2411: {
		index: 2411,
		text: `<p>Nothing truly good happens to mortals who deal with the People of the Flame, so you seek to avoid the presence of the other, who seems to be fascinated by you. But you soon find out that avoiding such a creature is no easy task, so you hope a show of force will make your intentions clear.</p>
<p><b>No Skill:</b> The other laughs at your gesture and with a wave of contempt, sends you hurtling miles away. You land on thick, soft brush: but at least you are alive, and now, apparently free from the attentions of the other. [S1/Have another player move you to any forest space]</p>
<p><b>Weapon Use, Protective Talisman, Sparkling Spear:</b> The other's contemptuous laughter at your gesture is cut short as your weapon strikes deep, causing showers of sparks to explode at the point of impact. Slowly, the other fades away. [D2]</p>`,
	},
	2412: {
		index: 2412,
		text: `<p>Nothing truly good happens to mortals who deal with the People of the Flame, so you avert the creature. [D-1]</p>`,
	},
	2413: {
		index: 2413,
		text: `<p>The otherworldly beauty of the 'efreeteh is too much for your mortal eyes to bear and you seek to be elsewhere lest your heart betrays your will. [S-1]</p>`,
	},
	2414: {
		index: 2414,
		text: `<p>Sitting on a large rock before you is a woman of amazing beauty, crying. You approach and ask how you can be of service. The woman turns to face you and you are immediately struck by the fact that she is not mortal. Yet, you stand by your offer, though you are a bit frightened. The 'efreeteh tells a tale of her lost love, taken by an evil sultan to be executed for being in love with a non-mortal.</p>
<p><b>No Skill:</b> You don't have the slightest notion on how to deal with a noble personage, evil or not. With many apologies you rescind your offer and go about your way. [S1]</p>
<p><b>Courtly Graces:</b> You are confident that you can help, but you need her help in looking the part: rich robes, platters full of gold and jewels, a large retinue. With such accoutrements, you not only gain an audience with the sultan but are able to free the 'efreeteh's love. As a reward, she leaves behind all of the gifts she created. [S1/W+5 (Max: Princely)]</p>`,
	},
	2415: {
		index: 2415,
		text: `<p>In the middle of nowhere, a being of great beauty appears before you. She says she needs your help and points to a small entrance in a cluster of stones. You are sure these rocks were not present seconds ago, and you suspect some mischief.</p>
<p><b>Male</b> [mandatory]: You agree to aid on one condition; that you delay no more than an hour as you have pressing business. Once inside her home, she stands revealed as a beautiful 'efreeteh. She has watched you for many months and has fallen in love with you. The next hour is spent in bliss, your wishes all coming true. When exactly one hour has passed, she points to her door. You say you can stay longer, but she has to honor her word. Nothing you say changes her mind and you leave, though your heart remains behind. [D1/S1/Seduction]</p>
<p><b>Female</b> [mandatory]: The woman assures you it will be worth your while: you tell her your "while" is worth a lot. Once inside the woman reveals herself to one of the People of the Flame and tells you she is in love with your cousin. She promises you a rich reward if you could but introduce her. This seems such a small matter and you so agree. The other fills your purses with gold and jewels as advance payment and you promise to fulfill your end of the deal. [W+4 (Max: Princely)]</p>`,
	},
	2416: {
		index: 2416,
		text: `<p>A beautiful woman appears before you. "Come, mortal, I need your aid in saving your people!" Before you can draw another breath, you stand with the fiery beauty in the middle of an auditorium, filled with an audience of all manner of djinn. You are here to plead the case for the continued survival of human race!</p>
<p><b>No Skill:</b> Your skills are not up to task at all and don't know why you were chosen. But with the fate of all men in your hands, you blather your way to a stay in the destruction by 100 years. [D1/Courtly Graces]</p>
<p><b>Bargaining and Evaluation, Courtly Graces:</b> You weave words as skillfully as the greatest of Persia's artisans weave their tapestries. The audience is delighted, and the 'efreeteh announces their verdict: that the People of the Clay shall be allowed to live. "I knew I chose wisely," whispers the 'efreeteh. With that, you find yourself back where you started, wondering out loud if you just had a waking dream. [D3]</p>
<p><b>Piety:</b> You know not what to say, so you kneel in prayer to Allah, begging for the human race to be spared. The gathered djinn nod approvingly and the 'efreeteh turns to you. "You have shown us that faith is still strong among your kind, which proves that humanity is worthy of life." The djinn bow in respect—and you find yourself back where you started. [D2/S1/Piety]</p>`,
	},
	2417: {
		index: 2417,
		text: `<p>From the other, you learn that you have an admirer among the People of the Flame. You will have to be careful to extricate yourself from this situation.</p>
<p><b>No Skill:</b> You hire a slave to play at being your spouse. Unfortunately, the slave doesn't perform well, but seeing the length to which you will go to avoid this relationship, the djinn leave you alone. [S1]</p>
<p><b>Acting and Disguise:</b> You purchase an elixir from an apothecary that will bring a pall of death about you. You seek out the love-stricken other and promptly die in front of them. Your performance is so convincing the other wails to the sky. As hot tears burn your chest, you feel yourself picked up, and flown in the air! You strive to keep your deception as the wind whips past you. Finally, you are laid to rest on cold stone. The other kisses your forehead and leaves. When you dare to stir, you find yourself in a tomb. [Move to the Sepulchre of Solomon and have an immediate encounter]</p>`,
	},
	2418: {
		index: 2418,
		text: `<p>Wails of anguish catch your attention and upon following the lovelorn sounds, you find yourself face to face with a striking, but unearthly figure. You are taken aback, but the other makes no threatening gesture. Instead, in tones soft as a whisper, yet clear in your mind, the other tell a tale of their lost love. Seeing an opportunity, you tell them of a human slave of such surpassing beauty and talent that by comparison any lost love could be forgotten. The other brightens at the prospect and asks what is needed. You respond that such a slave of marketable talents will cost a great sum—plus a commission. You take the money into town and spend a small portion of it on a beggar, along with some clothes and cleaning supplies. You direct them to their new lover, while you purchase a horse and leave town at speed. [W+3 (Max: Rich)/Acting and Disguise/Lose <em>Respected</em>/Next turn, instead of drawing an encounter card, encounter a Vengeful 'Efreet (Matrix M)]</p>`,
	},
	2419: {
		index: 2419,
		text: `<p>Upon hearing the other's tale of unrequited love, you sense an opportunity: you assure the other of your ability to reunite lovers for a small fee. The other pays you and listens to your instructions; to wait outside a certain home at a certain time. What you didn't say was that it is the home of a powerful wizard: let the two battle of them it out. At your khan, outside the city, you count your money while laughing at the prospect of what will happen when the two beings, when suddenly, your moneys melts away in your hands. It appears that someone else has gotten the last laugh. [S1/W-2 (Min: Poor)]</p>`,
	},
	2420: {
		index: 2420,
		text: `<p>You are most interested by your discovery, but you feel that time is of the essence, and head on to your destination rather than tarry overly long here. [Courtly Graces]</p>`,
	},
	2421: {
		index: 2421,
		text: `<p>As you approach the other, you call it to the attention of all those around you. They, too, are struck by its aspect, and recommend as one that you give it a wide berth. [D1]</p>`,
	},
	2422: {
		index: 2422,
		text: `<p>Something about the other makes you deeply uneasy, and you decide that it is better not to come too close. This takes you far off your route, but in the end, you feel safer for it. [Have another player move you two spaces in any direction]</p>`,
	},
	2423: {
		index: 2423,
		text: `<p>At night, your camp is overcome by an enormous cloud of screeching, flapping bats. Fearing for your life, and unable to find cover, you dive to the ground and pray for deliverance.</p>
<p><b>No Skill:</b> After being buffeted about for what feels like forever, the cloud of bats disappears as mysteriously as it arrived. Much of your camp has been destroyed, but at least you are alive. [S1/W-1 (Min: Respectable)]</p>
<p><b>Piety</b> [mandatory]: Confident that Allah would never let one as devout as you come to harm, you stand up among the bats, ignoring their many bites and cuts. You survive, but some of the bites are very slow to heal. [S1/<em>Diseased</em>]</p>`,
	},
	2424: {
		index: 2424,
		text: `<p>As you ride across the plain, you see a dark cloud of winged creatures turn and dive towards a lone wildebeest. To your shock and horror, the unfortunate animal is overcome almost instantly, reduced to no more than stripped bones. Your heart stops as the cloud turns and heads straight for you!</p>
<p>You know that you have no hope to survive without the aid of Allah, so you drop to your knees and begin to pray fervently.</p>
<p><em>Roll one die, adding one for Piety:</em></p>
<p>❖ 1–2: The creatures attack you viciously, tearing at your hands and face. To your amazement, they let you live, but the damage will take a long time to heal. [S1/Lose Appearance/<em>Wounded</em>]</p>
<p>❖ 3+: Praise be to Allah, for he is merciful! At the last moment before the creatures strike, they notice another wildebeest in the distance. Apparently, they prefer wildebeest to human meat. [D1/Piety]</p>`,
	},
	2425: {
		index: 2425,
		text: `<p>You see a cloud of locusts scouring the plain like the plague called by the prophet Musa against the Pharaoh. You know that you cannot hope to live if they catch you, so you turn your horse and ride as hard as you can the other way. As you ride, you pray for protection from the Most High.</p>
<p><b>No Skill:</b> Your horse proves too slow for the task, and the leaping insects begin to land on you. Luck is with you, however, and you and horse tumble into a fast-running river. You do not know where you are when you finally return to the shore, but at least it is far from the locusts. [D1/Luck/<em>Lost</em>]</p>
<p><b>Quick Thinking:</b> Your prayers are answered in a most unexpected way. You catch sight of sheltered cave near the road. Driving your mount into the darkness, you hastily cover the entrance with your blanket. Trapped within, you have no choice but to explore the cave, and discover that it is much more than it appears. [S1/Move to the Cave of Wonders and have an immediate encounter]</p>`,
	},
	2426: {
		index: 2426,
		text: `<p>Never before have you seen such a magnificent animal. Not wanting to spook the creature, you decide to watch it for a while from a safe hiding place.</p>
<p><b>No Skill:</b> You enjoy a pleasant afternoon watching the beautiful beast. [S1]</p>
<p><b>Acting and Disguise:</b> Binding the tall grass around you, and carefully masking your scent, you are able to lure the creature closer. Near enough to touch it, you are amazed by the glory of Allah that has been expressed in this noble animal. [D1/Scholarship/<em>Blessed</em>]</p>`,
	},
	2427: {
		index: 2427,
		text: `<p>Your host spent the entire evening telling you unbelievable tales of the fine horses in his stable. In the morning, you resolve to see the beasts for yourself.</p>
<p><b>No Skill:</b> Your host tells the truth! You doubt that even the Caliph owns animals as wondrous as these. [S2]</p>
<p><b>Stealth and Stealing:</b> Surely a mount such as one of these would make your travels much easier. You need only convince the stable hand to let you take one out for a ride... [S1/W+1 (Max: Rich)/<em>Outlaw</em>/Move three spaces in any direction]</p>`,
	},
	2428: {
		index: 2428,
		text: `<p>The villagers' tales of an animal so beautiful no huntsman can harm her have intrigued you. You are determined to remain here until you see the beast for yourself.</p>
<p><b>No Skill:</b> Despite your best efforts, the animal evades you. Tired and frustrated, you journey onward. [S-1/Lose <em>Determined</em>]</p>
<p><b>Storytelling:</b> By repeating the tales you heard in the village at every farm and lodge you discover, you eventually find the home of the creature. You are struck with amazement at the beauty of the beast, and leave greatly humbled by your encounter. [D1/S1/Scholarship]</p>`,
	},
	2429: {
		index: 2429,
		text: `<p>Though their appearance is hideous, something about the twisted creatures draws your attention and you cannot bear to look away. You find yourself examining them for many hours.</p>
<p><b>No Skill:</b> After watching the ugly brutes for quite some time, you begin to see patterns in their behavior that remind you of the actions of other animals and even of men. A serious study of these troglodytes could prove very enlightening. [S1/Scholarship]</p>
<p><b>Wisdom:</b> You gradually realize that the horrible creatures are also watching you! Lest their interest grow too strong, you make a hasty retreat to the safety of the road. [D1/S1]</p>`,
	},
	2430: {
		index: 2430,
		text: `<p>When the townsfolk told you their tale of the awful creatures that roam the streets at night, you knew you had to see them for yourself. Secure in your third-story apartment, you watch the street below through the narrowest crack in the shutters.</p>
<p><b>No Skill:</b> If only you had been wise enough to douse your lamp! The shambling forms spied your light, and to your amazement and terror quickly scramble up the walls of the house to seize you! Now you find yourself one of their number, stumbling along in the dark, seeking victims of your own. [D-1/S1/<em>Accursed</em>]</p>
<p><b>Appearance, Seduction:</b> The twisted forms have discovered you, attacking your house with heavy blows! Terrified, you fling open the shutters to attempt an escape. When you are revealed in all your beauty, they cease their attacks. Soon a crowd has gathered below you, and in the light of the dawn you can see that the monsters are only men, suffering under some terrible spell. You can only hope that the sultan's viziers can discover a cure. [D1/S1/Beguiling]</p>`,
	},
	2431: {
		index: 2431,
		text: `<p>At first, you dismissed the hushed tales of a haunted well near the village. But you heard it said so many times that you decide that you must investigate it for yourself. Hiding a safe distance away, you watch the well with great curiosity.</p>
<p><b>No Skill:</b> You discover that it is no ghost that haunts this well, but some horrific monster half-man and half-snake! You have no choice but to warn the villagers away from the well and send word to the sultan of this hideous beast. [S1/Stealth and Stealing]</p>
<p><b>Scholarship:</b> You are amazed to realize that the creature haunting the well is in reality a noble Nāgah, far from its home in the lands of the Mughals. They are attracted to deep water and often make their homes in wells or pools. You approach the creature, and convince him to move to a more remote location, that the villagers might no longer trouble him in his hermitage. [D1/S1/Courtly Graces]</p>`,
	},
	2432: {
		index: 2432,
		text: `<p>During a visit to a small lake-shore village, you discover that the fishermen are afraid to gather their catch. It seems some dark and sinister creature has made its home in the brackish waters.</p>
<p><b>No Skill:</b> After many long days and sleepless nights, you finally glimpse the black form of a sinuous lake beast. It is clearly too big for you to handle, but you think it makes a compelling tale. [S1]</p>
<p><b>Seamanship:</b> Using wooden pylons driven deep in the lakebed, you stretch nets across the narrowest part of the lake. Two days later, a black serpentine creature is ensnared! Rescued from their trials, the villagers reward you with their most valuable possession. [D1/S1/<b>Colored Fish</b>]</p>`,
	},
	2433: {
		index: 2433,
		text: `<p>For three nights you have pursued a beast so black you can see it only when you are not looking directly at it. You resolve to capture the creature that you might learn more about it.</p>
<p><b>No Skill:</b> You lure the beast into a secluded canyon from which there is no exit. But when you reach the end, the creature has vanished! Shaken by your brush with the supernatural, you hastily flee. [S1/Wilderness Lore]</p>
<p><b>Luck, Wilderness Lore:</b> You trick the beast by not pursuing it, luring it closer and closer to your fire. When it lures too close, you leap upon it and bind it with your rope! It is like a cat with shimmering black fur, and such a curious creature will surely fetch a fine price to a collector. [D1/S1/W+1 (Max: Rich)]</p>`,
	},
	2434: {
		index: 2434,
		text: `<p>Every time you try to sleep, you are awoken by the baying of some enormous dog. Twice you glimpse the mighty black animal. Perhaps if you snare him, he would make an effective guardian.</p>
<p><b>No Skill, Wilderness Lore</b> [mandatory]: You set careful snares and traps, but somehow the animal evades them with ease. Frustrated and half-crazed for lack of sleep, you stumble away into the wilderness. [S1/Enduring Hardship/Have another player move you to any land space]</p>
<p><b>Magic:</b> Recognizing the supernatural nature of the creature, you know that even the most elaborate traps will do nothing. Using a special charm you learned in your travels, you bind the creature with ancient words of power. After a few days, he becomes your loyal companion, protecting you as you sleep and vanishing during the day. [D1/Luck]</p>`,
	},
	2435: {
		index: 2435,
		text: `<p>The villagers tell you their tale of woe: how night after night, swarms of terrifying bats emerge from their hidden caves to prey upon men and livestock. Disease and injury threaten to destroy the entire village. If you can somehow trap the beasts in their caves, the villagers would be saved.</p>
<p><b>No Skill:</b> Bats come out only at night, so perhaps you can confuse them with light. You instruct the villagers to build great fires near the caves. Alas! The smoke and light of the fires serves only to drive the bats into a frenzy, redoubling their attacks. The villagers chase you off. [D-1/S1/<em>Scorned</em>]</p>
<p><b>Seamanship:</b> It occurs to you that you could cover the cave entrances with fishing nets, which the bats would be unable to escape. Purchasing nets from a nearby fishing village proves an easy task, and after a few nights, all of the caves are blocked. The villagers hail your clever solution. [D1/<em>Respected</em>]</p>`,
	},
	2436: {
		index: 2436,
		text: `<p>As soon as you enter the quiet glade, you feel your breath taken away. The beauty that surrounds you is truly a testament to the glory of the All-Merciful! Clouds of colored butterflies surround you. You wish you could share the beauty with others.</p>
<p><b>No Skill:</b> You try most carefully to capture a precious few, but alas the delicate creatures either avoid you or do not survive your clumsy efforts. Though you cannot share the experience, your soul feels warmed for your opportunity to see such wonder first hand. [S2]</p>
<p><b>Wisdom:</b> Realizing that great care would be required, you contrive to bait the creatures into a large jar you carry. Placing flowers within, you coax many inside and seal it loosely. When you present the wondrous creatures to the emir, he is impressed by your care and generosity, and he praises you for all to hear. [D1/<b>Robe of Honor</b>]</p>`,
	},
	2437: {
		index: 2437,
		text: `<p>Never before have you seen such a creature as the one flying about the crest of a nearby mountain. Surely the Sultan would be pleased to add such a fabulous creature to his menagerie!</p>
<p><b>No Skill:</b> You decide to lure the creature to the ground by staking some livestock where it will be easy to find. The winged creature soon swoops down to take the poor animal but cannot tear it free from the ropes. Casting a net about it, you soon capture the beast, to the delight and amusement of the sultan. [S1/Quick Thinking]</p>
<p><b>Appearance:</b> The beast is attracted to the lure you set out, but at the last moment it gazes upon you and forgets the tasty meal you have set out. Landing at your feet, it rests its head on your knee, entranced by your beauty. Acting on impulse, you climb onto the creatures back, and it happily flies you many leagues. [D1/S1/Move up to five spaces in any direction]</p>`,
	},
	2438: {
		index: 2438,
		text: `<p>With a shudder you awaken in the night to see the dim hazy outline of a great horse passing through your camp. You realize that you can see right through the beast!</p>
<p><b>No Skill:</b> You try to rope the horse, but your line passes through it without meeting any resistance. Terrified, you burrow deeper into your blankets and pray for morning to come. [S1]</p>
<p><b>Wilderness Lore:</b> Watching the animal, you see that it does not touch the ground or leave any tracks. It is a ghost! You cannot capture such a beast by mortal means. [S1]</p>
<p><b>Magic:</b> You realize quickly that this is no mortal creature, but a specter! You essay an enchantment to capture it.</p>
<p><em>Roll two dice, adding two for Magic at Master level:</em></p>
<p>❖ 2–10: The shimmering image vanishes before you can complete your spell. [S1]</p>
<p>❖ 11+: You chant the forbidden words of binding, and the beast is surrounded by a blue light. Quickly, you unravel the history of the ghost, and realize that it was the mount of a great sultan who was slain near here. The ghost leads you to the lost cairn, from which you recover a long-lost treasure. [D1/<b>Treasure</b>]</p>`,
	},
	2439: {
		index: 2439,
		text: `<p>For days, the villagers have been terrorized by a spectral visitor in the night. You believe it is some kind of hoax and resolve to capture those responsible.</p>
<p><b>No Skill:</b> You watch for many nights, but the specter doesn't appear. Perhaps you have scared it off. [S1/<em>Determined</em>]</p>
<p><b>Enduring Hardship:</b> You spend many nights in cold discomfort, watching the village carefully. Finally, the specter appears! You follow the mysterious figure back to its lair and discover there a troupe of burglars who have been using costumes to frighten the villagers and mask their own nefarious activities. When you tell the villagers of the trick, they quickly band together to bring the burglars to justice. [D1/S1/<em>Respected</em>]</p>`,
	},
	2440: {
		index: 2440,
		text: `<p>Across the stream, you see a shadowy horse, but you cannot make out the rider. Something about the beast draws your curiosity, and you try to catch it before it disappears into the night.</p>
<p><b>No Skill:</b> Try as you might, you cannot catch the shadowy form, which rides with greater speed than any living thing. You realize that you are chasing a phantom and had best give up before it steals your soul. [S1]</p>
<p><b>Scholarship:</b> You realize that you are chasing a phantom, and you cannot hope to catch it. Rather, you must lie in wait where it will appear the following night. You prepare yourself, and spring into action when the phantom next appears!</p>
<p><em>If you have Stealth and Stealing:</em> You catch the phantom unawares and capture it in a large glass bottle! Now you can force the phantom spirit to teach you its secrets. [D1/S1/Magic]</p>
<p><em>If not:</em> The phantom notices you long before you can leap for it. To your shock, it turns on you and leaps into your body. Now you find that you cannot control your own limbs! [S1/<em>Ensorcelled</em>]</p>`,
	},
	2441: {
		index: 2441,
		text: `<p>That Allah could allow such hideous beasts to profane the earth, you cannot understand. But you know that you cannot allow them to roam free and threaten the lives of innocent people any longer.</p>
<p><b>No Skill:</b> You attempt to lure the creatures into a trap, but they prove to be much faster than you imagined! Before the townsfolk can come to aid you, they have beaten you terribly. Your wounds will recover, but will your pride? [D-1/S1/<em>Scorned</em>]</p>
<p><b>Beguiling:</b> You convince some of the townsfolk to act as bait to lure the beasts into your trap. The creatures are much faster than you imagined, and you feel some guilt at the terrible fate that two of the townsfolk suffer, but now the creatures are safely locked away in cages. [D1/S1/Quick Thinking]</p>`,
	},
	2442: {
		index: 2442,
		text: `<p>The Sultan has offered an enormous reward for any who can capture the strange creature that has attacked his flocks unceasingly for few weeks. Eager to add his gems to your collection, you set out in search of the horrific beast you have heard so many tales about.</p>
<p><b>No Skill:</b> You know that you cannot harm the creature, so you devise a plan to lure it into a trap. Though it is hideous and ugly, you believe that it will be attracted to something beautiful. Unfortunately, the beautiful thing it is attracted to is you! [S1/W+1 (Max: Rich)/Seduction]</p>
<p><b>Stealth and Stealing:</b> While the beast is distracted by the lure of the flock, you creep up behind it. Catching it unawares, you strike him with a cudgel. Dragging the unconscious form before the sultan, you are amazed to learn that it is his own brother, enchanted by an evil sorceress! [D1/S1/W+2 (Max: Rich)]</p>`,
	},
	2443: {
		index: 2443,
		text: `<p>A horrific creature, with long gangly arms and a twisted visage, attacked your camp. Curiously, it did not harm you or steal anything of value. Only a few mundane cooking utensils are found to be missing. You wonder what strange creature would steal pots but not the food next to it. Intrigued, you track the beast to a ruined tower. It should be easy to trap it inside.</p>
<p><b>No Skill:</b> As you try to block the entrance, the creature panics and attacks you! Unable to defend yourself, you are soon knocked unconscious. You awaken later with a terrible headache, with the creature nowhere to be seen. [S1]</p>
<p><b>Storytelling:</b> You realize that the ruins are the tower of a great wizard. You have heard tales of his experiments gone terribly wrong. If you can trap him, perhaps you can force him to reveal his secrets!</p>
<p><em>If you have Beguiling:</em> You trick the former wizard into attacking you by blocking the entrance to the tower, and he does not suspect that a hidden net is waiting for him outside. Once snared, he is eager to trade his knowledge for his freedom. [D1/Magic]</p>
<p><em>If not:</em> The former wizard is easily tricked into your net, but you discover that he has more than talons to protect his secrets when he casts a terrible curse on you! [S2/<em>Beast Form</em>]</p>`,
	},
	2444: {
		index: 2444,
		text: `<p>Traveling through the plains, you are amazed to hear a thunderous cracking sound. Approaching, you realize that an enormous rukh is hatching from an egg the size of a palace! You know that the ravenous beast will surely eat all the livestock from the nearby village, so you draw your weapon and attack while it is vulnerable.</p>
<p><b>No Skill:</b> Though you are brave, and your arm mighty, you are no match for the terrible fury of the baby rukh. Thank Allah it finds you too small a morsel and flies away without eating you. Alas, the locals blame you for the loss of their flocks. [S1/<em>Scorned</em>]</p>
<p><b>Weapon Use:</b> It is fortunate that you still carry the hunting spear given to you by your princely friend, for without a weapon that long, you could not hope to prevail against such an enormous being. Though the spear is shattered, you manage to pierce the monster's heart. [D1/S1/Luck]</p>`,
	},
	2445: {
		index: 2445,
		text: `<p>You are amazed to realize that the shining white dome you thought would be shelter from the rain is actually the enormous shell of a rukh egg!</p>
<p><b>No Skill:</b> Eggs are waterproof, you realize, and taking up a great stone, you hammer your way into the great egg. You find not only shelter, but an ample supply of surprisingly tasty meat! [S1]</p>
<p><b>Enduring Hardship:</b> You cannot bring yourself to harm the magnificent egg or the creature within. Instead, you shelter in the shadow of the egg. When the rain stops, you are blessed with watching the return of the most magnificent bird you have ever laid eyes upon. [D1/S2/Scholarship]</p>`,
	},
	2446: {
		index: 2446,
		text: `<p>You have found the nest of a terrible rukh, the largest bird in all the world! These beasts have been known to devour entire herds in a single day. You know that you cannot let the eggs hatch, or the people of the valley below will be devastated by the ravenous creatures. But you had best hurry before their mother returns to the nest!</p>
<p><em>Roll two dice, adding one each for Luck, Wilderness Lore, and Fated. Subtract one if you are Accursed:</em></p>
<p>❖ 1–2: As you lift your axe to strike the first egg, you are lifted up into the air by the returning rukh. At least you can rest knowing that you were a tasty, if brief, repast for such a magnificent creature... [Death]</p>
<p>❖ 3–8: The rukh returns to the nest while you are in the middle of your grisly work! Enraged, she attacks you, but you escape her talons by hiding among the stones. [D1/S1/Wisdom]</p>
<p>❖ 9+: Luck is with you! You complete your task and escape without seeing any sign of the mother rukh. In return for your bravery, the people of the valley shower you with honors. [D1/S1/<b>Robe of Honor</b>]</p>`,
	},
	2447: {
		index: 2447,
		text: `<p>The sight of such a vain and self-absorbed man on such a noble steed drives you to violence. You decide to take it from him by force.</p>
<p><em>Roll two dice:</em></p>
<p>❖ 2–7: He may be a gilded popinjay, but you cannot deny his skills. The rider proves too much for you, and you are forced to flee. [D-1/Weapon Use]</p>
<p>❖ 8–12: With a daring stroke, you wound the self-important louse, and claim the horse for your own. If only you had known that he was the son of an emir... [S1/W+1 (Max: Respectable)/<em>Outlaw</em>]</p>`,
	},
	2448: {
		index: 2448,
		text: `<p>The creature may be the finest animal you have ever seen, but you cannot allow it to continue to harass the herds of the local shepherds. You prepare to rid them of the dangerous beast.</p>
<p><b>No Skill:</b> The creature is too dangerous to approach directly. You will have to stalk it with stealth and cunning. Careful to remain downwind, you are able to attack it with your bow. [D1/Stealth and Stealing]</p>
<p><b>Enduring Hardship:</b> You discover the favored hunting grounds of the beast. Using yourself as bait, you wait long hours into the night for it to appear. You feign sleep when it arrives, and you wait for it to creep into reach before you launch your attack. [D1/Acting and Disguise]</p>`,
	},
	2449: {
		index: 2449,
		text: `<p>There is something about the animal that causes you to fly into a rage. Perhaps it is just too perfect?</p>
<p><b>No Skill:</b> You assail the beast, but it you cannot find a weakness in its defense. Exhausted, you collapse. Do you imagine that it winks at you as it turns to leave? [S1]</p>
<p><b>Weapon Use:</b> Your suspicions are confirmed when you back the creature into a corner. With a puff of fiery smoke, the beast transforms before your eyes into a fearsome djinn! "Spare me, oh master!" he cries, and offers you a wondrous reward. [D1/S1/Choice of <b>Treasure</b> or You may lose up to two statuses of your choice]</p>`,
	},
	2450: {
		index: 2450,
		text: `<p>You see a merchant transporting an enormous egg in a wagon. You realize that he has found a rukh's egg! You decide to follow him from a safe distance.</p>
<p><b>No Skill:</b> You are not much surprised to see the egg's mother swoop down and scatter the caravan, claiming her egg again. At least you can find some valuables among the wreckage left behind. [S1/W+1 (Max: Respectable)]</p>
<p><b>Quick Thinking:</b> When you see the mother rukh appear on the horizon, you run to the merchant to warn him. Wisely, he abandons the egg and makes a hasty escape. He rewards you for saving his life. [D1/W+2 (Max: Rich)]</p>`,
	},
	2451: {
		index: 2451,
		text: `<p>Making your way up the treacherous mountain path, you are shocked to hear a thunderous roar from above you. Fearing an avalanche, you leap aside as a monstrous egg rolls past you!</p>
<p><b>No Skill:</b> Curious to see what happens, you follow the egg down the mountainside to find it smashed on the rocks. Perhaps the remains of the shell will fetch some coins at market. [S1/W+1 (Max: Respectable)]</p>
<p><b>Stealth and Stealing:</b> You remember tales of the rukh, the largest birds in the world, and the gems they often build their nests with. Knowing that the egg must have come from a nest, you creep up the mountainside. Distressed by the missing egg, the mother rukh takes little notice as you grab a bagful of shining rubies and make your escape. [S1/W+2 (Max: Princely)]</p>`,
	},
	2452: {
		index: 2452,
		text: `<p>You are intrigued by the shards of enormous eggshells you stumble upon during your journey. What kind of magnificent creature could have come from within? Following the trail of broken shells, you are amazed to find a blind rukh hatchling! You quickly bind the creature, and present it the Sultan as a gift. The Sultan is astounded by your generosity and demands that you remain in his court for a time. [D1/S1/Courtly Graces]</p>`,
	},
	2453: {
		index: 2453,
		text: `<p>Making your way along a narrow mountain path, you see a half-starved horse struggling along the path. Despite its poor condition, you can see from its fine saddle and harness that the horse belongs to someone of wealth and power. Such beasts are loyal beyond measure.</p>
<p><b>No Skill:</b> You follow the horse, hoping that it will lead you to its master. But the creature is weak and begins to stumble. You quickly offer the poor beast a bag of oats, which it greedily devours. Unfortunately, it seems that the noble animal has chosen you as a new master, and shows no interest in leading you any further. [S1/W+1 (Max: Respectable)]</p>
<p><b>Wilderness Lore:</b> You carefully approach the beast, and offer it a handful of grain. Giving it just enough to keep going, you coax it into guiding you to its master, whom you find starving and unconscious near the path. You revive the young emir, who is eager to reward you. [D1/S1/W+1 (Max: Rich)/<b>Treasure</b>]</p>`,
	},
	2454: {
		index: 2454,
		text: `<p>You wake from a deep slumber to find a small animal digging into your supplies, the poor beast's ribs clearly visible. Your sudden movement startles the creature, and it takes off, dragging your purse along behind it! You chase after the miserable creature, shouting.</p>
<p><b>No Skill:</b> The creature reaches its burrow before you can catch it. You console yourself to the fact that it won't find your coins particularly tasty. [S1/W-1 (Min: Poor)]</p>
<p><b>Quick Thinking:</b> It's clear that you won't be able to catch the creature. Grabbing up a rock, you throw it after the little beast. You miss, but the impact startles it enough to let go of your purse. [S1]</p>`,
	},
	2455: {
		index: 2455,
		text: `<p>Hunger gnaws your belly, and you can see that the animals here suffer the same as you. Out of arrows, you are forced to follow a gangly antelope, hoping that it will collapse before you do.</p>
<p><em>Roll one die, adding two each for Enduring Hardship and Determined:</em></p>
<p>❖ 1–3: Your hunger overcomes you. You collapse in to the dust. Sometime later, you wake, with no recollection of where you are or how you came to be there. [S1/Have another player move you to any land space]</p>
<p>❖ 4+: Your endurance proves greater than your prey. Though the meat is tough, it is enough to keep you going until you reach the next town. [D1/Wilderness Lore]</p>`,
	},
	2456: {
		index: 2456,
		text: `<p>Following the sounds of struggle, you emerge into the clearing to see a great cat locked in life-or-death battle with a larger animal. Without hesitation, you leap into the fray.</p>
<p><b>No Skill:</b> As soon as you land among the beasts, both turn on you, ravaging your body and tearing your flesh. [S1/<em>Crippled</em>]</p>
<p><b>Scholarship, Storytelling:</b> You remember a tale of beasts such as these and know what you must do. Drawing your bow, you fire an arrow, slaying the smaller creature instantly. The larger beast looks at you with great yellow eyes for a moment before slinking away into the trees. Taking the panther's pelt, you predict a profitable day in the market. [S1/W+1 (Max: Respectable)/Quick Thinking]</p>`,
	},
	2457: {
		index: 2457,
		text: `<p>In the middle of some nameless village, you come across some villagers mercilessly beating a dark misshapen creature. Though their victim is a twisted parody of a human, your heart goes out to him, and you feel you must intervene.</p>
<p><b>No Skill:</b> Striking out with your cudgel, you scatter the timid villagers. To your amazement, when you turn to help the unfortunate creature, it has transformed into a shimmering being of light! "You have aided me when none other would. May Allah guide your steps from this day forward!" [D1/S1/<em>Blessed</em>]</p>
<p><b>Bargaining and Evaluation:</b> After you chase away the villagers, you discover that you have rescued a mighty spirit! Knowing of their powers, you demand riches for your reward. "A good deed well done should be its own reward!" The spirit declares. Your greed is returned with justice as your gold is turned to dust. [D-1/S2/W-2 (Min: Poor)]</p>`,
	},
	2458: {
		index: 2458,
		text: `<p>Wandering through the woods without direction, you find a clearing. There you discover a black-furred creature, ensnared in some huntsman's trap! Unable to bear such suffering, you attempt to free the creature.</p>
<p><b>No Skill:</b> The huntsman appears just as you release the animal. He demands compensation for stealing his prey. You graciously offer him a reward. Softened by your kindness, he offers to guide you on your way. [S1/W-1 (Min: Respectable)/Wilderness Lore]</p>
<p><b>Appearance:</b> You free the creature from the trap and release it. But for days afterwards it follows you, entranced by your kindness and beauty. You learn much of the art of stalking by watching the soundless passage of the creature. [D1/S1/Stealth and Stealing]</p>`,
	},
	2459: {
		index: 2459,
		text: `<p>You have stumbled across the nest of a mighty rukh, the lone egg gleaming in the sun. But you are not alone: a band of robbers approaches, intent on stealing the egg. How can you allow such a noble creature to be enslaved by such ruffians?</p>
<p><b>No Skill:</b> You stand upon the egg, your blade in hand. The robbers laugh as they overwhelm you, leaving you battered in the now empty nest. [S1/Weapon Use/<em>Wounded</em>]</p>
<p><b>Acting and Disguise:</b> You could not hope to overcome the robbers with violence, so you choose trickery. Disguising yourself as one of their band, you whisper lies in their ears. Before long, you are able to turn them on each other! [D1/S1/Beguiling]</p>`,
	},
	2460: {
		index: 2460,
		text: `<p>In the dark of night, your soul quivers to the sound of mysterious chanting. Steeling your resolve, you approach the sound to discover a circle of evil Magian fire-worshippers, surrounding the egg of an enormous rukh!</p>
<p><b>No Skill:</b> You cower in the darkness, fearful for your life and praying for the All-Mighty to aid you. Perhaps it was in answer to your prayers that the mother of the egg arrived in time, sending the Magians fleeing for their lives! [D1/S1/Piety]</p>
<p><b>Quick Thinking:</b> You have heard that such dark rituals must be completed very carefully. Even a slight interruption can turn the spell on the casters. At what seems a crucial moment, you fling your water bag into their fire, scattering the coals and dousing the flame! You may never know what happened in the confusion and darkness that follows, but when dawn arrives, the egg is gone and the Magians lie quiet on the ground. [D1/S1/Magic]</p>`,
	},
	2461: {
		index: 2461,
		text: `<p>Rounding a bend in the path, you are surprised to find an enormous egg, surrounded by a band of curious villagers who seem intent on harming the egg.</p>
<p><b>No Skill:</b> You realize that the villagers could not dispatch such an egg without aid. You offer to help them. No sooner do you prepare to strike the egg then you regret your rash decision. With thunderous wings, the egg's mother appears! You are lucky to escape with your life. [S1/<em>Wounded</em>]</p>
<p><b>Wisdom:</b> You know that the villagers will only bring down the wrath of the egg's mother upon them. You tell them a tale of others who dared threaten the young of these mighty birds, and they are convinced to leave it well enough alone. [D1/Storytelling]</p>`,
	},
	2462: {
		index: 2462,
		text: `<p>For most of the morning, you have been watching the mass of black, taloned birds hanging over the road ahead. From time to time, some would dive to the earth below, before returning to the milling cloud. As you draw closer, you see that they are worrying a strange creature, half-woman, half-lion, with wings, that lies wounded on the ground, barely able to crawl. You ride forward to help the wounded beast.</p>
<p><b>No Skill:</b> Shouting and howling, you spur your mount and swing your sword above your head, hoping to chase off the blood-thirsty creatures. They scatter at your efforts. However, as you ride past the creature on the ground, it swipes out with its fierce claws, killing your horse in a single stroke. One should not expect gratitude from a monster! [D-1/S1/<em>Grief Stricken</em>]</p>
<p><b>Storytelling:</b> As you come closer, you recognize the creature on the ground as a sphinx from legend! You pause to light a torch and ride into the midst of the "birds," swinging the torch about like a censer and dispersing them. You keep your distance from the monster until you have exacted a promise from it to share with you the treasure of its centuries of preying on travelers. [D1/S1/W+1 (Max: Princely)]</p>`,
	},
	2463: {
		index: 2463,
		text: `<p>The twisted hunchback lunges at the poor nightingale, forcing it roughly into an overcrowded cage with many more of its kind. Their mournful cries break your heart and you are determined that they be free. But the mean hunchback refuses to release them, even when you offer him great riches!</p>
<p><b>No Skill, Weapon Use</b> [mandatory]: Angered by his rudeness, you strike the hunchback a vicious blow, sending him staggering. While he is stunned, you quickly free the beautiful birds and they make their escape. [D1]</p>
<p><b>Magic:</b> You see that only one punishment would be adequate for such a foul brute. Incanting terrible words, you transform the hunchback into a bird just like those he has snared. Forcing him into the cage, you look for a suitable owner to sell him to. [D1/S1/Bargaining and Evaluation/Lose Piety]</p>`,
	},
	2464: {
		index: 2464,
		text: `<p>You arrive at the palace of your distant kinsman. To your amazement, you find the halls abandoned, his servants all fled. You finally find your relative sitting uneasily in his chamber, muttering about a curse of wings that assails his palace night after night. You resolve to lend your aid in whatever way you can. That night, you watch from a place of concealment. You discover the cause of your friend's misfortune, as a cloud of black birds enters the palace and transforms into a woman.</p>
<p><b>No Skill, Appearance</b> [mandatory]: Before she can approach your cousin, you seize her. She gazes into your eyes, and you are lost at once. Succumbing to her charms, you satisfy her every request. In the morning, she is gone, but so too it seems is the curse that hung over your cousin. [D1/Seduction/<em>Love Struck</em>]</p>
<p><b>Magic:</b> You recognize that the ghost—for that what she is—is cursed to haunt this place. But with just a few words, you unravel the curse and free her; all that remains is a black feather. [D1/S2]</p>`,
	},
	2465: {
		index: 2465,
		text: `<p>The first thing you hear is the screams. Some terrible thing thrashes in the water—its wet, dripping tentacles lashing out at the men and horses struggling upon the bridge. Without hesitation, you leap to their aid, and with your sword you distract the beast long enough for the others to make good their escape.</p>
<p><b>No Skill:</b> Surely the only aid that can be given to such an abomination is death! You organize the others and take turns throwing stones at the beast until it is dead. [D1/S1]</p>
<p><b>Seamanship:</b> At a glance you know the nature of this beast—it is a sea-creature somehow trapped here when the river was swollen by floods in the spring. .With the assistance of the others, you rig together a harness and use it to haul the creature past the shallows to where it can return to its pelagic lair. [D1/S1/W+1 (Max: Rich)/Wisdom]</p>`,
	},
	2466: {
		index: 2466,
		text: `<p>The visage of the other is almost too much to bear. It's all you can do not to run away screaming—but the screams of the others nearby keep you rooted in place.</p>
<p><b>No Skill:</b> You remain rooted there until it is too late to be useful. You resolve never to hesitate like that in the future. [D2/<em>Determined</em>]</p>
<p><b>Determined</b> [mandatory]: As though you have leaden boots on your feet, you slowly and deliberately step forward, reaching out to the other victims until you touch skin. The spell is broken and suddenly you move like a flash of lightning, grabbing up people and getting them to safety. [D2/S2/Enduring Hardship]</p>`,
	},
	2467: {
		index: 2467,
		text: `<p>Upon closer examination, you realize the "creature" was—is—a man! An affliction this horrible needs your help and protection. You offer to see if the other's condition can be attended to by physicians.</p>
<p><b>No Skill:</b> The other says that many have tried and failed. The more you talk to the other the more you see of his condition. You recognize the boils from your travels. He is truly lost. You suggest a pilgrimage to Mecca to make his peace with Allah, and you offer to join him to make sure that he gets there. He is most grateful and sings your praises to one and all. [D2/Piety/Wilderness Lore/<em>Respected</em>]</p>
<p><b>Enduring Hardship:</b> You know the other to be wrong in his dismal thoughts. You have had his exact condition! It was very painful but you know a remedy—equally painful but unfailingly effective. [D2/Scholarship/<em>Respected</em>]</p>`,
	},
	2468: {
		index: 2468,
		text: `<p>You are awoken from your sleep by the sound of a rukh flying overhead. Leaping onto your horse, you set out to follow it, and it leads you to its nest and its lone egg. You have heard tales of these dangerous creatures destroying flocks and herds, so you rush to the Sultan to warn him of the danger. He dispatches his army to deal with the beast before the egg can hatch. Impressed by your wisdom, he makes you his trusted advisor. [D1/S1/<em>Vizier</em>]</p>`,
	},
	2469: {
		index: 2469,
		text: `<p>If you could only find a way to transport it, the enormous rukh egg would make you a very wealthy man. You approach the nearby village to recruit help.</p>
<p><b>No Skill:</b> As soon as they see the great egg, the greedy villagers turn on you! You have no choice but to watch them take the precious egg for themselves. [D-1/S1]</p>
<p><b>Beguiling:</b> You see the eyes of the villagers expand with greed as they view the egg for the first time. Seeing the danger, you threaten them with terrible curses should they betray you. Convinced you are a powerful wizard, they meekly obey your commands. [D1/Bargaining and Evaluation]</p>`,
	},
	2470: {
		index: 2470,
		text: `<p>You located the nest of a mighty rukh, and found a lone egg within. You know that the Sultan will reward you handsomely for it. You approach the local captain of the Sultan's troops for assistance transporting the egg. But the treacherous worm has you arrested!</p>
<p><b>No Skill:</b> You are cast into the captain's dungeon while he takes all the credit for your discovery. [S1/<em>Imprisoned</em>]</p>
<p><b>Seduction</b> and <b>Female:</b> You use all of your charms and wiles to convince the captain to share the rewards with you. So swayed is he by your seductive ways, he is ill-prepared when you tell the Sultan the truth of his greedy betrayal. The Sultan has him cast in irons and appoints you to the now-vacant position. [D1/S1/W+1 (Max: Rich)]</p>`,
	},
	2471: {
		index: 2471,
		text: `<p>The land is quiet as you ride through the fields, choked with the remains of slain livestock. The animals seem to have been drained of all blood by some terrible creature. You are right to worry about your own horses, as a great beast with leathery wings descends from the sky.</p>
<p><b>No Skill:</b> You have no choice but to flee. Sadly, your horse is too slow to flee the talons of the wyvern, and you find yourself on foot long before you reach the safety of the town. You are forced to purchase new supplies before you can continue your quest. [S1/W-1 (Min: Respectable)]</p>
<p><b>Courtly Graces:</b> Raising a banner gifted to you by the local emir, you ride hard for the walls of the town. Seeing the banner and fearing for their prince, the guardsmen rush out to aid you and chase off the beast. [D1/Acting and Disguise]</p>`,
	},
	2472: {
		index: 2472,
		text: `<p>You happen upon the largest flock of birds you could ever imagine—but these are no ordinary birds. Filled with wonder, you pursue them, hoping to find one who can tell you their secret.</p>
<p><b>No Skill:</b> You wander for days before the birds fly too far away for you to follow any further. Who will believe such a strange tale? [S1]</p>
<p><b>Piety:</b> You are amazed to find Shaykh Nasr surrounded by the great flock of birds! He tells you that you have found the great Parliament of the Birds, and invites you to explore his palace while he attends to the needs of the birds. [Have an immediate encounter in the Palace of 100 Closets (Matrix N)]</p>`,
	},
	2473: {
		index: 2473,
		text: `<p>You must have been cursed by some malicious spirit, for every time you try to eat, a flying creature of some kind steals the food from your very mouth! If you cannot find a way to be rid of these terrible beasts, you will surely starve. You have heard of a wise woman who makes her home in a forest near here, and you seek out her help.</p>
<p><em>Roll two dice:</em></p>
<p>❖ 2–4: She refuses to help you, leaving you to wander the wilderness until your hunger drives you mad. [Enduring Hardship/<em>Insane</em>]</p>
<p>❖ 5–8: She agrees to help you, but at a cost. [S1/<em>Under Geas</em>]</p>
<p>❖ 9+: She takes one look at you and immediately offers her aid. She tells you that dark forces seek to block your destiny. [D1/<em>Fated</em>/Lose <em>Accursed</em>]</p>`,
	},
	2474: {
		index: 2474,
		text: `<p>You were searching some ruins for a cache of precious gems, only to find them guarded by a dangerous and powerful serpent-like creature! You remember seeing a snake charmer in a small village a few days back. Perhaps you can convince him to share the secrets of his craft so you can avoid the terrible beast.</p>
<p><b>No Skill:</b> The snake charmer tells you that his secrets can only be shared with members of his religious sect. You realize that he is part of a Magian cult! You report him to the vizier, who rewards you for your diligence. Sadly, it is worth much less than the gems you hoped to recover. [D1/S1/W+1 (Max: Respectable)]</p>
<p><b>Bargaining and Evaluation:</b> The man refuses to share his secrets, but in exchange for a promise of half the gems, he agrees to help you. The snake creature is enthralled by his rhythmic music and movements, and you easily collect the prize. [S1/W+2 (Max: Rich)]</p>`,
	},
	2475: {
		index: 2475,
		text: `<p>Some creatures are simply too horrific to face alone. Having found one such beast, you know that you must find other people to aid you against it.</p>
<p><b>No Skill:</b> Lesser men abound and cannot be made to stand against their fear for any price. You learn that this is the only kind of men who make their homes in this town. [S1]</p>
<p><b>Courtly Graces:</b> Though you may not inspire the bravery of cowardly townsfolk, you do know the words that will motivate the captain of the guard. You soon find yourself beside him at the front of the column, confidently pursuing the trail of the monster. [D1/S1]</p>`,
	},
	2476: {
		index: 2476,
		text: `<p>With a single swipe of its mighty claw, the beast knocks you from your mount before you are even aware of it. Too shaken to fight, you stagger to your feet and flee towards the town.</p>
<p><em>Roll two dice, adding one each for Luck, Enduring Hardship, Blessed, and Fated:</em></p>
<p>❖ 2: Your feet fail you and the shapeless form leaps onto your back. The last thing you hear is a curious warbling sound—a sound ripped from your own throat! [Death]</p>
<p>❖ 3–7: You tumble down the hillside, the beast right behind, cutting and tearing at you with its great talons. Eventually, it gives up the pursuit, and you thank Allah for his mercy. [S1/Piety/<em>Wounded</em>]</p>
<p>❖ 8+: With a burst of strength from deep within, you put some distance between you and the creature before you tumble to the ground. Thankfully, you are close enough to the walls of the nearby town for the guards to see you, and their arrows chase the beast away. [D1]</p>`,
	},
	2477: {
		index: 2477,
		text: `<p>You have finally found your way again after wandering in the mountains for many days. Somehow, you have attracted the attention of a hunting cat. It is a great creature, with enormous fangs that curve like scimitars. You can hear its hungry growls in the night, but so far it hasn't been brave enough to approach you. But your own hunger has weakened you, and you cannot hope to fight it off alone.</p>
<p><b>No Skill:</b> It is too late. You stagger down the mountain, but the hungry beast draws near. Your only hope is to find a camp, but the cat leaps before you do, and darkness washes over you. You come to some time later, your wounds bound in thick bandages, and the smiling face of a woodsman gazing down upon you. [S1/<em>Wounded</em>]</p>
<p><b>Luck:</b> You pick your way carefully down the mountain, hoping that the column of smoke you see belongs to a woodsman's hovel or camp. You stagger into the clearing barely conscious. You hear the growls of the beast as a burly woodsman approaches you. It seems the terrible beast will go hungry for another day. [S1/Wilderness Lore]</p>`,
	},
	2478: {
		index: 2478,
		text: `<p>You awake in the middle of the night to the sound of a small animal digging through your belongings. It appears to be a small cat, hungry and lost, with many minor injuries. You know little about animals, so you take the small creature to seek more knowledgeable help.</p>
<p><b>No Skill:</b> You find a small cottage where an old woman keeps many such cats. She thanks you for helping save her lost kitten, and asks if there is any way she can reward you for your kindness. [S1/You may lose one status of your choice]</p>
<p><b>Appearance:</b> You find an ugly hag of a woman who offers to help the kitten in exchange for the tiniest reward: a single heartfelt kiss. After a long pause, you agree to her terms, and lean in, eyes closed. To your amazement, her kiss is passionate and pleasant, and when you open your eyes, she is revealed to be a beautiful young maiden. "Thank you for breaking the curse," she exclaims before leaping into your arms for another embrace. [D1/S1/<em>Beloved</em>]</p>`,
	},
	2479: {
		index: 2479,
		text: `<p>The terrible flood has finally ended, and the land is a washed out plain of mud and mire. You begin looking for survivors when you hear a mournful whimpering from beneath an overturned wagon. You dig beneath it to discover a half-starved and half-drowned hunting hound. You share the last of your food with the ragged animal, hoping that it won't take too long to find help.</p>
<p><b>No Skill:</b> With the dog to help you, you soon find some waterlogged food supplies. It takes a few days, but you finally leave the flooded plain behind and continue on your journey. [D1/Enduring Hardship]</p>
<p><b>Luck:</b> As you and your new companion wander the water-blasted landscape, you are surprised to see a column of horsemen approaching you. At the head rides none other than the Sultan himself! He is delighted to see you, but even more delighted to see the dog. For rescuing his most prized hound, he awards you with the highest of honors. [D1/S1/<b>Robe of Honor</b>]</p>`,
	},
	2480: {
		index: 2480,
		text: `<p>As you are sitting in a seaside tavern, you look up to see the other, accompanied a grizzled old sailor. The other slides onto the bench next to you. "My friend," he says, "how would you like a job?" You notice the old sailor appears to be hiding something behind his back. You reach for your sword and gesture for the "recruiter" to find himself another mark; you have no desire to wake up on a ship way out at sea.</p>
<p><b>No Skill:</b> The other scoffs at you, and before you can react, the thug swings quickly. The next thing you know, the ground beneath you sways and only the smell of salt fills your nostrils. You are told that your service will last one year, so you had best learn fast. [D1/Seamanship/<em>Under Geas</em>]</p>
<p><b>Weapon Use:</b> You flash your sword towards his face and he stumbles backward. The others in the tavern, most of whom are his crewmates, rise to defend their companion. You fight bravely, and your foresight may have saved you from years aboard a ship. Now if only you could find a place to recover from the beating. [D1/S1/Quick Thinking/<em>Wounded</em>]</p>`,
	},
	2481: {
		index: 2481,
		text: `<p>Traveling along a lonely road, you come to a fork. One side leads into a dank jungle, the other into a scorching desert. Standing in the middle of the road is a scrawny other. "Bwah hah ha!" he says, "You will never guess. One way leads to certain doom, the other to uncertain riches." You leap forward, grabbing the annoying one by the throat, "Tell me or you won't live to learn of my choice!" The other coughs and looks you in the eye, "Now now, that isn't how the game is played. But since you are so keen, I will give you a hint: In one the water is low, in one the water is high, but in neither comes the water of Allah."</p>
<p><em>Roll two dice, adding one each for Scholarship, Wilderness Lore, and Wisdom:</em></p>
<p>❖ 2–5: You strike the infuriating wretch. Immediately, two large men appear from the shadows. You fight them well, but are robbed of all you own. [W−3 (Min: Penniless)]</p>
<p>❖ 6–8: Water high is where you can use it. You head off into the jungle. It is humid, true, but the lack of trails and the inability to see makes it hard to navigate. [D1/<em>Lost</em>]</p>
<p>❖ 9–10: Water low must be the desert. Surely water kept safely out of the sun can always be found. You head off into the desert, anxious to find your reward. [D1/Wilderness Lore]</p>
<p>❖ 11+: If the water of Allah is not in the desert, and not in the jungle, where could it be? You head straight, ignoring both paths. Soon you find a crystal pool, in which lay many treasures. Touching none, you continue on your way. [D2/S1/<em>Blessed</em>]</p>`,
	},
	2482: {
		index: 2482,
		text: `<p>You are sitting on a cushion, enjoying your evening meal, when you are approached by a young couple, who join you. When their mate is distracted elsewhere, one of them coos softly in your ear, whispering erotic words. You are deeply offended, pushing the salacious one to the floor.</p>
<p><b>No Skill:</b> You huff self-righteously, "I'll have nothing to do with you." The couple skulks off and you notice your purse is missing. [S1/W−1 (Min: Penniless)]</p>
<p><b>Seduction:</b> Shocked and dismayed at your lack of decorum, you offer many apologies and much recompense. You suggest a good meal and pleasant conversation. The other eyes you cautiously for a moment, then smiles and accepts. [D1/S1/<em>Beloved</em>]</p>`,
	},
	2483: {
		index: 2483,
		text: `<p>Accused of stealing, you are brought to a jail and tossed in a cell near another prisoner. To your amazement, the other turns out to be a former traveling companion. The other explains that the guards here often hold people on false charges, seeking to extract money from their kin. The two of you plot an escape: you will hurl objects at each other, and when the jailors intervene, you seize the keys and break for freedom. You face off, shouting and hurling loose stones and bricks.</p>
<p><b>No Skill:</b> The guards do not fall for your ruse. They simply gather to watch the show. [S1/<em>Imprisoned</em>]</p>
<p><b>Acting and Disguise:</b> The two of you clash mightily; your display is impressive and seems to shake the very walls of the jail. After a short time, the guards enter the cell to separate you and your former companion. At that moment, the two of you leap upon the guards, surprising and disarming them, and then make good your escape. When you are safe, the other offers to teach you what he has learned since you last parted. [S2/Stealth and Stealing]</p>`,
	},
	2484: {
		index: 2484,
		text: `<p>You watch a cold-blooded murderer taken away by the local magistrate, the blood of your favorite cousin still on her hands. You are filled with rage and can barely contain the urge to kill the woman who has made your cousin's wife a widow and his children fatherless. You will make her pay for her crimes.</p>
<p><b>No Skill, Weapon Use</b> [mandatory]: Late that night, you head over to the jail. You pretend to stagger and offer the guard your wine skin. "I can drink no more," you explain. The jailor gladly consumes the wine and falls asleep. You wake the prisoner and, once she recognizes you, you drive your sword into her chest. [D1/Acting and Disguise/Lose Piety]</p>
<p><b>Stealth and Stealing:</b> As darkness falls, you creep quietly into the jail. For long hours, you move slowly and carefully, hiding in impossible positions, barely breathing. In time, you reach the murderer's cell and make your presence known. Although she is at your mercy, you cannot bring yourself to kill her. However, you make sure she knows you could have. [S1/Enduring Hardship/<em>Blessed</em>/<em>Grief Stricken</em>]</p>`,
	},
	2485: {
		index: 2485,
		text: `<p>On a cold, dry night, you lie under a palm near an old oasis. In the light of your dying fire, you see a woman dressed in the armor of the ancient Greeks. She is surrounded by a circle of illuminated sigils. As you approach in wonder, she tells you a tale: "Deep in the mountains to the south laired a horrible monster with a hundred tails and a dozen tooth-filled heads. My Amazons and I sought to slay it, but it was controlled by a foul sorcerer. We triumphed over both monster and master, but with his dying breath, the wizard cursed us. Each night when the moon is fullest, I appear in this circle in the site of my former home. I cannot be free until I am bested in battle. Will you challenge me?"</p>
<p><b>No Skill:</b> Wracked with pity, you draw your sword and raise it above your head to honor of your foe. The fight is fierce, but you cannot match the woman warrior's years of experience. [S2/<em>Crippled</em>]</p>
<p><b>Magic:</b> You shake your head, "What if there is another way?" Hope lights on her face. In time, you are able to break the magic of the sigils, freeing the valiant woman. As she steps from the circle, time catches up and she crumbles to dust. Only a brilliant sword remains to mark her passage, the last of her line. [D2/<b>Thunderbolt Sword</b>]</p>`,
	},
	2486: {
		index: 2486,
		text: `<p>As you sit under a palm passing a hot day, you are joined by another, who begins a sad tale of loss. Spouse, children, parents, friends, relations—all have perished or, for one reason or another, have departed. At first, you are sympathetic, but in time, the other's litany becomes tiresome. It seems the other does nothing about what fate has decreed except complain. You lean over and strike the other—perhaps that will inspire action!</p>
<p><b>No Skill:</b> Taken aback, the other recoils. "Why did you do that?" With nothing more to say, you shake your head and walk away. [D1]</p>
<p><b>Scholarship:</b> The other leaps up, dagger at the ready. You speak harshly, "Sit down, shut up, and listen!" The force of your action and words compels the other. You explain that companionship, while always desired, is unnecessary for a seeker of knowledge. Reading, research, drafting—these are all worthy endeavors that are best completed alone with no distractions. As you talk, the other's eyes brighten as new possibilities come to light. [D1/S1/Beguiling]</p>`,
	},
	2487: {
		index: 2487,
		text: `<p>As you approach an oasis, deep in the desert, you hear a most beautiful, haunting song. Drawing closer, you spy a beautiful youth singing by the water. The other's song tells of lost love, unrequited love, and the despair of frustrated dreams. Yet something is odd. You notice the pool at her feet is nearly filled with human bones. Panic grips you but still you cannot help but move closer. Drawing your sword, you prepare to strike.</p>
<p><b>No Skill:</b> Summoning all your will, you bring your weapon to bear against this haunting figure. Your blow is feeble and faulting. The enchantress smiles, showing razor sharp teeth and serpent tongue of an accursed marid! You are lucky to escape with only a handful of deep bites. [S1/<em>Wounded</em>]</p>
<p><b>Magic:</b> Realizing that you are under a spell, you whisper words of great power. This allows your blow to strike true, despite your shaking hand and muddled mind. The figure shrieks, showing vicious teeth and a pointed tongue. After it flees into the desert, you discover a most interesting item just below the surface of the pool. [D1/S1/<b>Treasure</b>]</p>`,
	},
	2488: {
		index: 2488,
		text: `<p>You speak with another of shared experiences: struggling to survive, learning hard lessons, and seeing many strange and wondrous things. The other expresses a loneliness birthed by the road that you find matched in your own soul. You ask what compels the other to keep traveling. It seems that the local prince was hoarding so much gold that the village was starving. The other snuck in to the prince's palace, stole some of the gold, distributed much of it to the neighbors, and fled into the hills. Returning after many years, the other had found that home was no longer familiar. Recognizing the story as one involving your own cousin, who had been executed for accepting some of the stolen gold, you are incensed. You draw your weapon to exact retribution.</p>
<p><b>No Skill:</b> The other sighs, saddened by your response. The fight is long, but ultimately inconclusive. The traveler departs, never to see home again. [S1]</p>
<p><b>Weapon Use:</b> The other is an accomplished swordfighter, and the battle is a long one. As the fight continues, you feel the full weight of the other's melancholy, and you cannot help but marvel at the traveler's grace and manners. When you bring the defeated other before the prince, you plead for leniency, explaining of the other's regrets, experiences, and nobility. The prince is touched by your deeds and is merciful in judgment. [D1/S1/Courtly Graces]</p>`,
	},
	2489: {
		index: 2489,
		text: `<p>One moment, you were on a short trip across a large body of water. The next, you are clinging to a plank with little but your sword and a box of hard tack. You spy a small boat off in the distance. Unfortunately, the person in that boat is worse off than you, and demands that you share what little food you have. You refuse, and a desperate fight ensues. As you are both sun-scorched and malnourished, the fight does not last long.</p>
<p><b>No Skill, Weapon Use</b> (mandatory): Refusing to be bested, you push the other into the water. As the body sinks beneath the surface, your conscience cries out in regret. By the time you are rescued by a passing vessel, you are inconsolable. [D1/<em>Grief Stricken</em>]</p>
<p><b>Luck:</b> When you recover, you decide to share your food. The other offers to alternate rowing with you. You set off, unsure of the direction, but filled with new resolve. In time, you happen across a vessel and are rescued. [D2/S1/Enduring Hardship]</p>`,
	},
	2490: {
		index: 2490,
		text: `<p>Your caravan is stopped for the night in a particularly desolate place. You awake to the sounds of someone rooting through your possessions. Grabbing your blade, you accost a dirty and thin wretch, quickly subduing and tying the other to your cart. The desperate one cries, "Please spare me! I have been wandering the desert for days in search of food."</p>
<p><b>No Skill:</b> You thunder, "I am not interested in your tales. Nothing excuses theft!" You drive the hungry one off. [D1]</p>
<p><b>Wilderness Lore:</b> Although ill-inclined to grant mercy, your heart softens a bit. You refuse to part with any food, but you do explain how to extract water from certain desert plants and further, which other plants are nourishing despite their foul taste. The other grovels in gratitude, and in thanks tells you a tale of some ruins a short distance away. Come the daylight, you go there and find an ancient treasure. [D2/S1/<b>Treasure</b>]</p>`,
	},
	2491: {
		index: 2491,
		text: `<p>While enjoying the library of a local scholar, you hear frustrated and loud sighs. Unable to concentrate with this distraction, you confront the rude person. The other stands before you, holding a clutch of scrolls and looking confused. You demand to know what is wrong and the other tells you of their desire to become a greater scholar, and also of his lack of ideas of how to begin or what to study.</p>
<p><b>No Skill:</b> You admonish the youth, explaining that not all wisdom comes from books. The other sets off to explore the world. You hear later that the journey was not a successful one. [D1]</p>
<p><b>Piety:</b> You scold the youth; there is one great path that precedes all other knowledge of the universe. You take the scrolls from his hands and guide him to a copy of the Koran. The other blesses you and begins to study. [D2/<em>Blessed</em>]</p>`,
	},
	2492: {
		index: 2492,
		text: `<p>While visiting an inn, you end up in conversation with a group of fellow travelers, sharing tales of some of your adventurers. When you are ready to depart, the other stands up abruptly and bars your path. "You have been overly familiar with the one I love, and are drawing her into a path of corruption and immorality!" Not wishing to be bothered with this lovesick fool, you cuff him soundly, sending him sprawling.</p>
<p><b>No Skill:</b> As the patrons drag the unfortunate one out into the street, the innkeeper apologizes profusely but asks you to go before there is further trouble. [S1]</p>
<p><b>Acting and Disguise:</b> You draw your sword and stand over the humbled other. You tell him that if he wishes to fight, perhaps he should focus his energies at something more useful than fleeting affections. Instead of jealous fits and poorly executed attacks, he should devote himself to service to the needy. Inspired, he gathers his things and leaves that night. The innkeeper will have no further trouble from him. [D1/S1/Storytelling]</p>`,
	},
	2493: {
		index: 2493,
		text: `<p>Walking your horse along a path by some water, you are beset by the other, raving about a missing love whom he apparently thinks you have abducted. With a flash of your blade, you quickly disarm him. He bursts into tears and tells you of his betrothed, who was taken just like yourself several days ago. He is desperate to discover her fate.</p>
<p><b>No Skill:</b> You berate him, calling him a fool and a criminal. He renews his attack and you wound him severely. As you travel on, you regret your rash action. [D1/Lose Quick Thinking]</p>
<p><b>Enduring Hardship, Wilderness Lore:</b> You feel pity for the other, for you have felt such loss in your heart before. You send several days searching the local area. Although the terrain is harsh and inhospitable, you find some tracks leading to a nearby village. There you pick up the trail of the one who took the man's love. Grateful, the other tells you of his courtship and how he plans to greet his love when he finds her. [D1/S1/Seduction]</p>`,
	},
	2494: {
		index: 2494,
		text: `<p>You are approached by one who is determined to win the love of another. The other says, "My beloved's family does not approve, but I believe the fates guide us. I know that you are one who believes that love conquers all, and I have taken it onto myself to sell your livestock to pay for a generous dowry to sway her parents." Enraged, you strike the other. Then you go to reclaim your goods.</p>
<p><b>No Skill:</b> You have limited success, alas—the family has already spent most of what they received. [D-1/W-2 (Min: Poor)]</p>
<p><b>Bargaining and Evaluation:</b> Despite your actions, the other's affection only deepens. You are astounded by the love they show and you wonder how you could ever have stood in their way. You work out a plan whereby the other will work for you after the marriage to repay the dowry, and all hail you for your kindness. [D2/S1/<em>Respected</em>]</p>`,
	},
	2495: {
		index: 2495,
		text: `<p>You meet another in a busy market street. You begin to converse, and you learn that the other is of noble birth but has been cast out of the ancestral home for being too talkative (imagine that!). You learn of the other's hopes and dreams, neighbors and friends, principles and concerns. You cannot get a word in edgewise. Finally you decide that if you are ever to be rid of this friendly but talkative pest, you must help.</p>
<p><b>No Skill:</b> You finally cut the garrulous one off. You explain that actions are needed now, not words. The other thanks you mightily but then launches into another tale. You realize this is a hopeless cause, and turn your back on the other. [D1/S1]</p>
<p><b>Courtly Graces:</b> You decide that what this young person needs is lessons in self-restraint. You teach the other that the best approach for a noble is laconic. Over time, and after countless interruptions, the youth begins to understand. The two of you return to the ancestral home and the family is delighted in the change in their scion. The family bestows on you a royal mark. [S1/<b>Robe of Honor</b>]</p>`,
	},
	2496: {
		index: 2496,
		text: `<p>Traveling down a busy road, you come across the other wailing inconsolably over the body of a dying dog. As you offer comfort, the other begins to babble about how the dog was a loyal servant, how it was a true friend, and how a callous cart driver ran the dog over and did not stop. You promise to help.</p>
<p><b>No Skill:</b> You dash off to find a healer, but the crotchety old man will have nothing to do with a common animal. Your pleas are ignored. [S1]</p>
<p><b>Wilderness Lore:</b> Taking certain plant stems from your pouch, you make a poultice and press it into the wound. This stops the bleeding and aids against infection. You realize this is only a temporary solution, however, and send the other for a kindly healer you know as you tend the dog. When the old woman arrives, she is impressed with your knowledge and quick action. You offer to teach her your remedy in exchange for her care of the dog. She agrees, and in mere days the animal is healthy and happy again. [D1/Bargaining and Evaluation]</p>`,
	},
	2497: {
		index: 2497,
		text: `<p>As you sit comfortably in the shade of a large palm, a young other joins you. The other is so forlorn, you cannot help but ask what ails the other. After a tentative pause, a tale comes gushing forth. The story involves long, tedious descriptions, vague and uninteresting characters in vague and uninteresting situations, and seemingly very little point. Unwilling to drive the person away, you continue to listen, offering only small comments here and there.</p>
<p><b>No Skill:</b> Your mind drifts off. In the fullness of time, the other comes to a conclusion, and stands. "Thank you, stranger, for listening to my tale. It was good to get it off my chest." You nod numbly as the other walks off. [D1]</p>
<p><b>Wisdom:</b> After a time, you realize the other simply needs someone to listen to them. After a few hours, the tale comes to an end. You provide some advice taken from your experiences and offer words of encouragement. The other's face brightens. The now contented one departs, wishing you the blessings of the Most High for all days. [D1/<em>Blessed</em> (1 use)]</p>`,
	},
	2498: {
		index: 2498,
		text: `<p>Perhaps it was the promise of reward, or perhaps just the need for adventure. Whatever the case, when a holy man asked you to meet him to find a great treasure, you agreed readily. You were somewhat surprised to find yourself among a dozen other adventurers, seeking the glory or riches such a prize offered. In the end, it was more a race than a hunt. It came down to following the others when you were lost and trying to lose them when you knew the way.</p>
<p><em>Roll two dice, adding one each for Luck, Magic, and Scholarship:</em></p>
<p>❖ 2–4: In your haste, you improperly translated a section of text on the map. Had you done it correctly, you would have been forewarned of the curse awaiting you. [D1/<em>Beast Form</em>]</p>
<p>❖ 5–8: You spend more time following than leading, and in the end you arrive safely . . . just as another adventurer claims the lamp. [S1]</p>
<p>❖ 9–11: You are able to keep a mere step ahead of the others and arrive at the cave. You find that the lamp is not the only thing hiding here! You take the lamp to the dervish and keep the rest. [S1/Choice of W+2 (Max: Princely) or <b>Treasure</b>]</p>
<p>❖ 12+: You are so accomplished that you arrive at the lamp's hiding place a full day before any others. You decide that the lamp could serve you well in your exploits and surely you can do as great deeds with it as any other could! [D1/S1/<b>Magic Lamp</b>]</p>`,
	},
	2499: {
		index: 2499,
		text: `<p>Hearing of your adventures, a dervish seeks your aid. This other's nephew, the child of his only sister has been abducted by pirates. Stirred by this tragic tale, you head out immediately to retrieve the child. You track the sea-dogs and discover that they have forced the noble personage to be a common servant, cleaning decks and dancing for their pleasure!</p>
<p><b>No Skill:</b> On retrospect, entering into combat with a hundred armed pirates was not your wisest course of action. You barely make it out alive. [S1/<em>Wounded</em>]</p>
<p><b>Acting and Disguise:</b> You outfit yourself as a pirate and stride boldly on board. None think to challenge you as you lead the heir away. On the way home, the rescued one becomes infatuated with you. [D1/S1/<em>Beloved</em>]</p>`,
	},
};
